The method:
String.prototype.format = function() {
return this.replace(/%([0-9]+)/g, (s, n) => arguments[Number(n) - 1]);
};
So you'd use something like:
const attacker = BattleManager._subject.name();
const skill = BattleManager._subject.currentAction().item().name
const defender = BattleManager._targets[0].name();
const text = "%1 casts %2 on %3".format(attacker, skill, defender);

