I actually hadn't seen the earlier threads, must've been using search terms that were too generic.
ATT_turan's code here seems to do the job
, and I was able to mod it so %3 returns the action-doer as well:
Code:
Window_BattleLog.prototype.displayAction = function(subject, item) {
    var numMethods = this._methods.length;
    if (DataManager.isSkill(item)) {
        if (item.message1) {
            this.push('addText', subject.name() + item.message1.format(item.name, BattleManager._targets[0].name(), BattleManager._subject.name()));
        }
        if (item.message2) {
            this.push('addText', item.message2.format(item.name, BattleManager._targets[0].name(), BattleManager._subject.name()));
        }
    } else {
        this.push('addText', TextManager.useItem.format(subject.name(), item.name));
    }
    if (this._methods.length === numMethods) {
        this.push('wait');
    }
};
So it can accommodate stuff like "Light begins to gather around %3" or "A spectral green thread appears between %3 and %2."
